from PySide6 import QtWidgets, QtCore
from PySide6.QtCore import QMetaObject, QSize, Qt
from PySide6.QtGui import QIcon
from PySide6.QtWidgets import QLabel, QLineEdit, QPushButton, QSizePolicy, QDialog

from videotrans.configure.config import tr, ROOT_DIR, settings, params
from videotrans.configure.constants import MINIMAX_TTS_MODELS, MINIMAX_ASR_MODELS
from videotrans.util.help_misc import open_url


class Ui_minimaxi(QDialog):
    def __init__(self):
        super().__init__()
        self.setWindowIcon(QIcon(f"{ROOT_DIR}/videotrans/styles/icon.ico"))
        self.setupUi(self)
    def setupUi(self, minimaxiform):
        self.has_done = False
        if not minimaxiform.objectName():
            minimaxiform.setObjectName("minimaxiform")
        minimaxiform.setWindowModality(Qt.NonModal)
        minimaxiform.resize(800, 300)
        minimaxiform.setMaximumSize(QSize(800, 300))

        v1 = QtWidgets.QVBoxLayout(minimaxiform)
        h1 = QtWidgets.QHBoxLayout()
        label_api = QLabel()
        label_api.setObjectName("label_api")
        label_api.setText(tr('API minimax'))
        self.apiurl = QtWidgets.QComboBox()
        self.apiurl.setObjectName("apiurl")
        self.apiurl.addItems(["api.minimax.cn", "api.minimax.io"])
        h1.addWidget(label_api)
        h1.addWidget(self.apiurl)
        v1.addLayout(h1)
        

        h3 = QtWidgets.QHBoxLayout()
        label_3 = QLabel()
        label_3.setObjectName("label_3")
        label_3.setText(tr("SK"))
        self.apikey = QLineEdit()
        self.apikey.setObjectName("apikey")
        h3.addWidget(label_3)
        h3.addWidget(self.apikey)



        h5 = QtWidgets.QHBoxLayout()
        label_5 = QLabel()
        label_5.setText(tr("Emotion"))
        self.emotion = QtWidgets.QComboBox()
        self.emotion.addItems(["happy", "sad", "angry", "fearful", "disgusted", "surprised", "neutral"])
        h5.addWidget(label_5)
        h5.addWidget(self.emotion)


        h_tts_model = QtWidgets.QHBoxLayout()
        label_6 = QLabel()
        label_6.setText(tr('From  Text  Into  Speech')+tr("Model"))
        self.tts_model = QtWidgets.QComboBox()
        self.tts_model.addItems(MINIMAX_TTS_MODELS.split(','))
        h_tts_model.addWidget(label_6)
        h_tts_model.addWidget(self.tts_model)


        v1.addLayout(h3)
        v1.addLayout(h5)
        v1.addLayout(h_tts_model)
        # Text start
        h_text_model = QtWidgets.QHBoxLayout()
        label_text = QtWidgets.QLabel()
        label_text.setObjectName("label_text")
        label_text.setText(tr('Text  Or Srt  Translation')+tr("Model"))
        self.text_model = QtWidgets.QComboBox()
        self.text_model.setMinimumSize(QtCore.QSize(0, 35))
        self.text_model.setObjectName("text_model")
        h_text_model.addWidget(label_text)
        h_text_model.addWidget(self.text_model)
        v1.addLayout(h_text_model)

        h_asr_model = QtWidgets.QHBoxLayout()
        label_asr = QtWidgets.QLabel()
        label_asr.setObjectName("label_asr")
        label_asr.setText(tr('Speech Recognit')+tr("Model"))
        self.asr_model = QtWidgets.QComboBox()
        self.asr_model.setMinimumSize(QtCore.QSize(0, 35))
        self.asr_model.setObjectName("asr_model")
        self.asr_model.addItems(MINIMAX_ASR_MODELS.strip().split(','))
        h_asr_model.addWidget(label_asr)
        h_asr_model.addWidget(self.asr_model)
        v1.addLayout(h_asr_model)

        h_token = QtWidgets.QHBoxLayout()
        label_token = QtWidgets.QLabel()
        label_token.setObjectName("label_token")
        label_token.setText(tr("Maximum output token"))
        self.max_token = QtWidgets.QLineEdit()
        self.max_token.setMinimumSize(QtCore.QSize(0, 35))
        self.max_token.setObjectName("max_token")

        self.minimaxi_thinking = QtWidgets.QCheckBox()
        self.minimaxi_thinking.setObjectName("minimaxi_thinking")
        self.minimaxi_thinking.setText("Thinking")
        h_token.addWidget(label_token)
        h_token.addWidget(self.max_token)
        h_token.addWidget(self.minimaxi_thinking)
        v1.addLayout(h_token)

        label_allmodels = QtWidgets.QLabel()
        label_allmodels.setObjectName("label_allmodels")
        label_allmodels.setText(
            tr("Fill in all available models, separated by commas. After filling in, you can select them above"))
        v1.addWidget(label_allmodels)

        self.edit_allmodels = QtWidgets.QPlainTextEdit()
        self.edit_allmodels.setObjectName("edit_allmodels")
        v1.addWidget(self.edit_allmodels)

        label_4 = QtWidgets.QLabel()
        label_4.setObjectName("label_4")
        self.template = QtWidgets.QPlainTextEdit()
        self.template.setObjectName("template")
        self.template.setReadOnly(True)
        self.template.setPlainText(tr("Prompt: Please open the {} file directly to modify it", 'minimaxi', 'minimaxi'))

        v1.addWidget(label_4)
        v1.addWidget(self.template)
        # TTS end
        h4 = QtWidgets.QHBoxLayout()
        self.save = QPushButton()
        self.save.setObjectName("save")
        self.save.setMinimumSize(QSize(0, 35))
        self.test = QPushButton()
        self.test.setObjectName("test")
        self.test.setMinimumSize(QSize(0, 35))

        help_btn = QtWidgets.QPushButton()
        help_btn.setMinimumSize(QtCore.QSize(0, 35))
        help_btn.setStyleSheet("background-color: rgba(255, 255, 255,0)")
        help_btn.setObjectName("help_btn")
        help_btn.setCursor(Qt.PointingHandCursor)
        help_btn.setText(tr("Fill out the tutorial"))
        help_btn.clicked.connect(lambda: open_url(url='https://pyvideotrans.com/minimaxi'))

        h4.addWidget(self.save)
        h4.addWidget(self.test)
        h4.addWidget(help_btn)
        v1.addLayout(h4)

        self.retranslateUi(minimaxiform)

        QMetaObject.connectSlotsByName(minimaxiform)

    def update_ui(self):
        allmodels_str = settings.get('minimaxi_model','')
        allmodels = str(allmodels_str).split(',')
        self.text_model.clear()
        self.text_model.addItems(allmodels)
        self.edit_allmodels.setPlainText(str(allmodels_str))

        self.apikey.setText(str(params.get("minimaxi_apikey",'')))
        self.apiurl.setCurrentText(str(params.get("minimaxi_apiurl",'api.minimax.cn')))
        self.emotion.setCurrentText(str(params.get("minimaxi_emotion",'')))
        self.tts_model.setCurrentText(str(params.get("minimaxi_tts_model",'')))
        self.asr_model.setCurrentText(str(params.get("minimaxi_asr_model",'')))

        self.max_token.setText(str(params.get("minimax_max_token",'8192')))
        self.text_model.setCurrentText(str(params.get("minimaxi_text_model",'')))
        self.minimaxi_thinking.setChecked(bool(params.get("minimaxi_thinking",False)))


    def retranslateUi(self, minimaxiform):
        minimaxiform.setWindowTitle("Minimaxi API")
        self.save.setText(tr("Save"))
        self.apikey.setPlaceholderText( tr("SK"))
        self.test.setText(tr("Test"))

